select 
	t.id as 'transit_job_id',
    t.internalId as 'internal_id',
    t.country as 'country_id',
    t.startPlace as 'start_place',
    t.endPlace as 'end_place',
    t.startMileage as 'start_mileage',
	t.endMileage as 'end_mileage',
    t.driver as 'driver_name',
	t.driverId as 'driver_id',
	t.driverCompany as 'driver_company',
    UNIX_TIMESTAMP(t.startTime) as 'start_date',
	UNIX_TIMESTAMP(t.endTime) as 'end_date',
	UNIX_TIMESTAMP(t.createdAt) as 'created_at',
	t.createdById as 'created_by_id',
	t.createdByName as 'created_by_name',
	UNIX_TIMESTAMP(t.updatedAt) as 'updated_at',
	t.updatedById as 'updated_by_id',
	t.updatedByName as 'updated_by_name',
	UNIX_TIMESTAMP(t.deletedAt) as 'deleted_at',
	t.deletedById as 'deleted_by_id',
	t.deletedByName as 'deleted_by_name',
    UNIX_TIMESTAMP(t.checkinAt) as 'checkin_at',
	t.checkinById as 'checkin_by_id',
	t.checkinByName as 'checkin_by_name',
    UNIX_TIMESTAMP(t.checkoutAt) as 'checkout_at',
	t.checkoutById as 'checkout_by_id',
	t.checkoutByName as 'checkout_by_name',
	ifnull(t.transitType, 'not specified') as 'transit_type',
	t.status as 'transit_job_status',
	t.comment as 'transit_job_comment',
    t.pendingCars as 'pending_cars'
from fcgCar.transitJob t
where t.updatedAt >= '{{params.start_ts}}' and t.updatedAt < '{{params.end_ts}}'